CREATE OR REPLACE FUNCTION public.combat_v2_stats(p_cp_base numeric, p_pts jsonb, p_role text, p_b jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
